-- ============================================
-- LUMA — Correction : 'Se plaindre poliment d'un plat' avait un faux choix
-- ============================================

update scenarios set content = '{"characters": {"alex": "Alex (serveur)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "How is everything?", "text_fr": "Tout se passe bien ?", "choices": [{"text": "Actually, my food is cold.", "next": "n2"}, {"text": "Everything''s great, thank you!", "next": "end_fine"}]}, "n2": {"speaker": "alex", "text": "I''m so sorry! Should I reheat it or bring a new one?", "text_fr": "Je suis vraiment désolé ! Je le réchauffe ou j''en refais un ?", "choices": [{"text": "A new one would be great, thank you.", "next": "n3"}, {"text": "Reheating is fine, thank you.", "next": "end_reheat"}]}, "n3": {"speaker": "alex", "text": "Of course, and I''ll take it off your bill for the trouble.", "text_fr": "Bien sûr, et je le retire de l''addition pour le désagrément.", "choices": [{"text": "That''s very kind, thank you.", "next": "end_new"}]}, "end_fine": {"speaker": "alex", "text": "Wonderful, enjoy your meal!", "text_fr": "Parfait, bon appétit !", "end": true, "ending_label": "Repas apprécié 😊"}, "end_reheat": {"speaker": "alex", "text": "I''ll have it back to you in two minutes.", "text_fr": "Je vous le ramène dans deux minutes.", "end": true, "ending_label": "Plat réchauffé ✅"}, "end_new": {"speaker": "alex", "text": "I''ll bring a fresh plate right away, on the house.", "text_fr": "J''apporte une assiette fraîche tout de suite, offerte par la maison.", "end": true, "ending_label": "Plat refait et offert 🍽️"}}}'::jsonb, is_playable = true
where title = 'Se plaindre poliment d''un plat'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
